def IsLabelledTerm (t : S.reducedImage besselS) (p : S.Classes × S.G E) :=
  (S.IsNearRep c p.1 p.2 ∧ S.HasLevel j p.2) ∧ ∃ s, p.2 ∈ S.termsOver c
  s p.1 ∧ (Subgroup.groupEquivQuotientProdSubgroup s).2 = t

